const now = new Date();
const yesterday = new Date(now);
yesterday.setDate(yesterday.getDate());
const startOfDay = new Date(yesterday);
startOfDay.setHours(0, 0, 0, 0);
const endOfDay = new Date(yesterday);
endOfDay.setHours(23, 59, 59, 999);
const brDate = yesterday.toLocaleDateString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  weekday: 'long',
  day: '2-digit',
  month: 'long',
  year: 'numeric'
});
const formattedDate = brDate.charAt(0).toUpperCase() + brDate.slice(1);
const sessionId = `newsletter_${Date.now()}`;
return [{
  json: {
    session_id: sessionId,
    date_display: formattedDate,
    date_query: yesterday.toISOString().split('T')[0],
    timestamp_start: startOfDay.toISOString(),
    timestamp_end: endOfDay.toISOString(),
    edition_subject: `📊 Minerals Trading Daily - ${formattedDate}`
  }
}];

const initData = $('INIT DATA').first().json;
const posts = $('BUSCAR POSTS DO DIA').all().map(item => item.json);
const allPrices = $('BUSCAR PRECOS PLATTS').all().map(item => item.json);
const perplexityResponse = $('PERPLEXITY MERCADO').first().json;
const marketContext = perplexityResponse.choices ? perplexityResponse.choices[0].message.content : 'Contexto de mercado nao disponivel';
const postsFormatted = posts.length > 0 ? posts.map((p, i) => `${i + 1}. ${p.title}\n   Resumo: ${(p.meta_description || p.content || '').substring(0, 200)}...`).join('\n\n') : 'Nenhum post publicado hoje.';
const pricesBySymbol = {};
allPrices.forEach(p => { if (!pricesBySymbol[p.symbol] || p.assessed_date > pricesBySymbol[p.symbol].assessed_date) { pricesBySymbol[p.symbol] = p; } });
const priceConfig = [
  { symbol: 'IODBZ00', name: 'IODEX CFR China 62% Fe', category: 'benchmark' },
  { symbol: 'IOPRM00', name: 'IO Fines Fe 65%', category: 'benchmark' },
  { symbol: 'IODFE00', name: 'IO Fines Fe 58%', category: 'benchmark' },
  { symbol: 'IODMR00', name: 'Mid Range Diff 60-63.5% Fe', category: 'differential' },
  { symbol: 'IODFG00', name: 'Fe Diff per 1% (55-60% Fines)', category: 'differential' },
  { symbol: 'IODFI00', name: 'Silica Diff per 1% (55-60% Fines)', category: 'differential' },
  { symbol: 'IODFH00', name: 'Alumina Diff per 1% <5% (55-60% Fines)', category: 'differential' },
  { symbol: 'IODAL00', name: 'Alumina Diff per 1% (1-2.5%)', category: 'differential' },
  { symbol: 'IODAM00', name: 'Alumina Diff per 1% (2.5-4%)', category: 'differential' },
  { symbol: 'IODSK00', name: 'Silica Diff per 1% (3-4.5%)', category: 'differential' },
  { symbol: 'IODSL00', name: 'Silica Diff per 1% (4.5-6.5%)', category: 'differential' },
  { symbol: 'IODSM00', name: 'Silica Diff per 1% (6.5-9%)', category: 'differential' }
];
const formattedPrices = priceConfig.map(config => { const priceData = pricesBySymbol[config.symbol]; if (!priceData) return null; return { symbol: config.symbol, name: config.name, category: config.category, price: priceData.price, change: priceData.chg, change_pct: priceData.chg_percent, date: priceData.assessed_date, unit: priceData.curr_uom || '$/DMT' }; }).filter(p => p !== null);
const benchmarks = formattedPrices.filter(p => p.category === 'benchmark');
const differentials = formattedPrices.filter(p => p.category === 'differential');
const pricesText = `\n📊 PRECOS BENCHMARK:\n${benchmarks.map(p => `• ${p.name}: US$ ${p.price} ${p.unit} ${p.change ? `(${p.change > 0 ? '+' : ''}${p.change})` : ''}`).join('\n')}\n\n📈 DIFERENCIAIS DE QUALIDADE:\n${differentials.map(p => `• ${p.name}: US$ ${p.price} ${p.unit}`).join('\n')}\n`;
const iodex = pricesBySymbol['IODBZ00'] || {};
return [{ json: { ...initData, posts: posts, posts_count: posts.length, posts_formatted: postsFormatted, all_prices: formattedPrices, benchmarks: benchmarks, differentials: differentials, prices_text: pricesText, price_data: { iodex_62: iodex.price || 'N/A', change: iodex.chg || '0', change_pct: iodex.chg_percent || '0', date: iodex.assessed_date || initData.date_query }, market_context: marketContext, posts_ids: posts.map(p => p.id) } }];

const prevData = $('CONSOLIDAR DADOS').first().json;
const aiResponse = $input.first().json;
let content;
try {
  let responseText = aiResponse.output || (aiResponse.message && aiResponse.message.content) || aiResponse.content || JSON.stringify(aiResponse);
  if (typeof responseText === 'object') { responseText = JSON.stringify(responseText); }
  responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  responseText = responseText.replace(/^\n+/, '').trim();
  if (responseText.startsWith('{') && responseText.includes('}')) {
    const lastBrace = responseText.lastIndexOf('}');
    responseText = responseText.substring(0, lastBrace + 1);
    content = JSON.parse(responseText);
  } else { throw new Error('Resposta nao e JSON valido'); }
} catch (e) {
  content = { resumo_executivo: 'Erro ao processar conteudo: ' + e.message, destaques: ['Verifique os dados de entrada'], perspectivas: 'Analise nao disponivel.', whatsapp_text: '📊 MTD Newsletter - Erro no processamento', subject_line: 'Minerals Trading Daily' };
}
const imagePrompt = 'Professional financial newsletter header image for iron ore market report. Modern, clean design with subtle mining/commodity trading elements. Color palette: deep blue, silver, and touches of iron red. Abstract representation of global trade, shipping, and mining. Corporate and sophisticated style. No text in image.';
return [{ json: { ...prevData, newsletter_content: content, image_prompt: imagePrompt, subject: content.subject_line || prevData.edition_subject, whatsapp_text: content.whatsapp_text || '📊 Minerals Trading Daily' } }];

const htmlData = $('GERAR HTML').first().json;
const currentItem = $input.first();
const hasImage = currentItem.binary && currentItem.binary.twitter_image;
const binaryData = hasImage ? currentItem.binary : undefined;
const subject = htmlData.subject || htmlData.edition_subject || (htmlData.newsletter_content && htmlData.newsletter_content.subject_line) || `📊 Minerals Trading Daily - ${new Date().toLocaleDateString('pt-BR')}`;
console.log('=== CONSOLIDAR FINAL ===');
console.log('Subject:', subject);
console.log('Has Image:', hasImage);
console.log('HTML length:', (htmlData.content_html || '').length);
return [{ json: { ...htmlData, subject: subject, has_image: hasImage, image_status: hasImage ? 'generated' : 'failed', image_mime_type: hasImage ? 'image/png' : null }, binary: binaryData }];

const data = $('CONSOLIDAR FINAL').first().json;
const newsletterId = $('SALVAR NEWSLETTER').first().json.id;
const sessionId = data.session_id;
const content = data.newsletter_content || {};
const benchmarks = data.benchmarks || [];
const differentials = data.differentials || [];

// Formatar precos
const formatPrice = (p) => {
  const change = parseFloat(p.change) || 0;
  const emoji = change > 0 ? '🟢' : (change < 0 ? '🔴' : '⚪');
  const sign = change > 0 ? '+' : '';
  return `• ${p.name}: US$ ${p.price} ${emoji} ${sign}${change.toFixed(2)}`;
};

const benchmarkText = benchmarks.length > 0 
  ? benchmarks.map(formatPrice).join('\n') 
  : 'Nenhum preco disponivel';

// Resumo truncado
const resumo = content.resumo_executivo || '';
const resumoTruncado = resumo.length > 500 ? resumo.substring(0, 500) + '...' : resumo;

// Destaques
const destaques = (content.destaques || []).slice(0, 5).map((d, i) => `${i + 1}. ${d}`).join('\n');

// Montar mensagem simples
let message = `📰 *NEWSLETTER PREVIEW*\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n\n`;
message += `📅 *Data:* ${data.date_display || 'N/A'}\n`;
message += `📧 *Assunto:* ${data.subject || 'Minerals Trading Daily'}\n`;
message += `📝 *Posts incluidos:* ${data.posts_count || 0}\n\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `💰 *PRECOS BENCHMARK:*\n\n${benchmarkText}\n\n`;
message += `📈 *Diferenciais:* ${differentials.length} indicadores\n\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📝 *RESUMO:*\n\n${resumoTruncado}\n\n`;

if (destaques) {
  message += `━━━━━━━━━━━━━━━━━━━━━\n`;
  message += `📌 *DESTAQUES:*\n\n${destaques}\n\n`;
}

message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `📱 *VERSAO WHATSAPP:*\n\n${data.whatsapp_text || '📊 Minerals Trading Daily'}\n\n`;
message += `━━━━━━━━━━━━━━━━━━━━━\n`;
message += `🖼 *Imagem:* ${data.has_image ? '✅ Gerada' : '❌ Falhou'}\n`;

// Botoes simplificados
const buttons = {
  inline_keyboard: [
    [
      { text: '✅ Aprovar e Enviar Email', callback_data: `nl_approve_${sessionId}` }
    ],
    [
      { text: '🖼 Ver Imagem', callback_data: `nl_view_image_${sessionId}` },
      { text: '🔄 Nova Imagem', callback_data: `nl_regen_image_${sessionId}` }
    ],
    [
      { text: '❌ Cancelar', callback_data: `nl_cancel_${sessionId}` }
    ]
  ]
};

return [{
  json: {
    chat_id: '8375309778',
    text: message,
    parse_mode: 'Markdown',
    reply_markup: JSON.stringify(buttons),
    session_id: sessionId,
    newsletter_id: newsletterId,
    has_image: data.has_image || false
  }
}];
